"""Concatenate the stage files into one compilable file (scratch files cannot import each other)."""
import sys
parts = ["Stage1.lean", "Stage2a.lean", "Stage2b.lean", "Stage2c.lean"]
d = "scratch/unif-printed/"
out = ["import ZInQKernel.HDecomp.Analytic.Uniformization\n",
       "\n/-! # unif-printed: `UniformizationLeafAll` from printed leaves (generated by build_unif.py from "
       + ", ".join(parts) + ") -/\n"]
for p in parts:
    s = open(d + p).read()
    lines = [l for l in s.splitlines(True) if not l.startswith("import ")]
    out.append("\n-- ===== " + p + " =====\n")
    out.append("".join(lines))
open(d + (sys.argv[1] if len(sys.argv) > 1 else "Unif.lean"), "w").write("".join(out))
